import { chromium } from "npm:playwright";
import { BASE_URL } from "../_shared/deno-helpers.ts";

// headless: false so a window opens; slowMo pauses between actions.
const browser = await chromium.launch({ headless: false, slowMo: 600 });
const page = await browser.newPage();

await page.goto(BASE_URL);
await page.getByPlaceholder("Enter Email").fill("leela@gmail.com");
await page.getByPlaceholder("Enter Password").fill("Leela@123");
await page.getByRole("button", { name: "Login" }).click();
await page.waitForURL("**/dashboard");

console.log("landed on:", page.url());
await browser.close();

