const browser2 = await chromium.launch({ headless: false, slowMo: 300 });
const page2 = await browser2.newPage();
await page2.goto(BASE_URL);

const started = Date.now();
try {
  // No such field. Watch the window: nothing happens, and it keeps trying.
  await page2.getByPlaceholder("Enter Username").fill("leela", { timeout: 4000 });
} catch (err) {
  console.log("failed after", Date.now() - started, "ms");
  console.log((err as Error).message.split("\n").slice(0, 4).join("\n"));
}

await browser2.close();

