// What each artefact answers. Read it as a lookup table.
const artefacts = [
  { kind: "screenshot", answers: "what did the page look like at the moment it failed?" },
  { kind: "video",      answers: "what happened in the seconds before?" },
  { kind: "trace",      answers: "every action, DOM snapshot, network call and console line" },
];

for (const a of artefacts) console.log(`${a.kind.padEnd(11)} ${a.answers}`);

console.log("\nopen a trace with:  npx playwright show-trace <path-to-trace.zip>");

